SELECT balance FROM accounts WHERE id = 'A' FOR UPDATE;
SELECT balance FROM accounts WHERE id = 'B' FOR UPDATE;
UPDATE accounts SET balance = balance - 50 WHERE id='A';
UPDATE accounts SET balance = balance + 50 WHERE id='B';
COMMIT;
